import{V as a}from"./chunks/VerificationResults.Clypp_x6.js";import{o as s,c as r,ah as t,E as o}from"./chunks/framework.B_OU15-2.js";const u=JSON.parse('{"title":"Verification","description":"","frontmatter":{},"headers":[],"relativePath":"verification/index.md","filePath":"verification/index.md"}'),n={name:"verification/index.md"},p=Object.assign(n,{setup(i){return(l,e)=>(s(),r("div",null,[e[0]||(e[0]=t('<h1 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h1><p>Celox results for the pinned <a href="https://github.com/chipsalliance/sv-tests" target="_blank" rel="noreferrer">sv-tests</a> corpus. Switch between <strong>Main tests</strong>, <strong>Cores</strong>, and <strong>Imported</strong>, then search by language feature or test-suite tag. Only Celox results are displayed. The layout follows the <a href="https://chipsalliance.github.io/sv-tests-results/" target="_blank" rel="noreferrer">upstream dashboard</a>.</p>',2)),o(a),e[1]||(e[1]=t('<h2 id="reading-the-results" tabindex="-1">Reading the results <a class="header-anchor" href="#reading-the-results" aria-label="Permalink to &quot;Reading the results&quot;">​</a></h2><p><strong>Main tests</strong> come from the current checkout&#39;s reviewed <code>expected.tsv</code> on master. They are a baseline assembled from reviewed verdicts, rather than a fresh full run. The source link identifies a commit containing that baseline; it is not a single simulator build or measurement date. Main baseline changes appear on the next website deployment.</p><p><strong>Cores</strong> and <strong>Imported</strong> are measured by the official upstream runner in a separate daily/manual workflow, outside PR gates. The page starts with checked-in measurements and loads newer complete daily results when available. Each group retains its own source revision and measurement time. Collection failures do not replace the last complete public result. Raw results and logs are retained as workflow artifacts for 14 days.</p><p>Skipped cases are excluded from the executed denominator. A dash means there are no executed cases, not a zero-percent score. Some core fixtures exclude Celox through upstream&#39;s <code>compatible-runners</code> metadata; those remain skipped and visible. The pinned CVA6 testbench has two unavailable include paths. Its failure is reported as an upstream input issue, not language support.</p><p>Tags overlap: a case can contribute to several tag rows but counts only once in the overall totals. Two-state and four-state results remain separate. Parsing and elaboration passes do not establish simulation correctness. Negative tests can pass because of an unsupported construct. Some imported cases check process success without validating their printed checks, so an official pass can still contain <code>Failed</code> output. These scores measure official test outcomes, not coverage of the language standard. Expand the execution details to inspect modes and diagnostics.</p><p>Local measurements use <code>heliodor-dev</code>; daily CI uses <code>release</code>. Upstream timeouts apply in both configurations, so build settings and machine load can affect results.</p>',6))]))}});export{u as __pageData,p as default};
